const groups=Object.freeze({
 'ch7s4-console-zero-build-solo-victory-cup':'console-vc',
 'ch5s3-solo-victory-cup':'2024-vc-qualifier',
 'ch5s3-zb-solo-victory':'2024-vc-qualifier',
 'ch6s3-playstation-cup':'attendance',
 'ch7s2-playstation-clix-cup-br':'attendance',
 'ch7s4-performance-evaluation-trios':'attendance',
 'ch7s4-inoxtag-icon-cup-battle-royale':'attendance',
 'ch7s4-override-persona-5-royal-cup-reload':'attendance',
 'ch7s2-fncs-division-1':'attendance'
});
const safeSame=(a,b)=>a&&b&&
 ['date','region','tournamentId','event',...numberFields].every(k=>a[k]===b[k])&&
 members(a).slice().sort().join('|')===members(b).slice().sort().join('|');
const preciseRound=u=>u.searchParams.get('round');
function scanEvidence(row,scans){
 let url;
 try{url=new URL(row.source)}catch{throw Error('invalid source URL')}
 assert(url.protocol==='https:'&&url.hostname==='www.fortnite.com'&&
  !url.username&&!url.password&&!url.hash&&
  /^\/competitive\/events\/[^/]+\/$/.test(url.pathname)&&
  url.searchParams.get('region')===row.region,'invalid source '+row.id);
 const eventId=decodeURIComponent(url.pathname.split('/')[3]),windowId=preciseRound(url);
 assert(windowId&&windowId.startsWith(row.seasonId+'_')&&windowId.endsWith('_'+row.region),
  'window/source mismatch '+row.id);
 const key='epicgames_'+eventId+'_'+row.region+'/'+windowId,found=[];
 for(const [scope,scan] of Object.entries(scans)){
  const cp=scan.windows?.[key];
  if(!cp)continue;
  const matching=cp.proposals?.find(x=>x.id===row.id);
  if(matching){
   assert(sameScannedCandidate(matching,row),'source vs proposal changed '+row.id);
   found.push({scope,cp});
  }
 }
 assert(found.length>0,'no checkpoint '+row.id);
 found.sort((a,b)=>Number(b.cp.complete)-Number(a.cp.complete)||Number(b.cp.pages)-Number(a.cp.pages));
 const cp=found[0].cp;
 assert(cp.rankingOrderValid===true&&Number.isSafeInteger(cp.pages)&&cp.pages>=1&&
  Number.isSafeInteger(cp.nextPage)&&cp.nextPage>=1&&
  Number.isSafeInteger(cp.lastSeenRank)&&cp.lastSeenRank>=row.rank&&
  !cp.lastErrorCode&&!cp.lastError&&!cp.retryAfter&&!cp.emptyAttempts,
  'leaderboard partial/invalid/retrying '+row.id);
 const observed=Date.parse(cp.lastSuccessAt||'');
 assert(Number.isFinite(observed)&&observed>=Date.parse(row.date+'T00:00:00Z')+4*3600000,
  'unsettled leaderboard '+row.id);
 return {eventId,windowId,key,cp};
}
function approve(row,db,scans,calendars){
 assert(row&&row.verified===true&&/^auto-s\d+-[a-f0-9]{12}$/.test(row.id)&&
  numberFields.every(k=>Number.isSafeInteger(row[k])&&row[k] >=(k==='rank'||k==='matches'?1:0))&&
  row.vrs<=row.matches,'scores or verification '+row?.id);
 const cat=db.tournaments.catalog.find(x=>x.id===row.tournamentId);
 assert(cat&&cat.id in groups&&cat.seasonId===row.seasonId&&cat.name===row.event&&
  Array.isArray(cat.sourceEventIds)&&['solo','duo','trio','squad'].includes(cat.team),
  'catalog or category mismatch '+row.id);
 const {eventId,windowId,key}=scanEvidence(row,scans);
 assert(cat.sourceEventIds.includes(eventId),'catalog source unknown '+row.id);
 const names=members(row),required={solo:1,duo:2,trio:3,squad:4}[cat.team];
 assert(names.length===required&&new Set(names).size===required&&
  row.player===names.join(' / ')&&
  names.every(x=>db.players.candidates.some(p=>p.name===x)),
  'unconfirmed player/team '+row.id);
 if(row.teamAccountIds){
  const accountMap=new Map(db.verifiedAccounts.map(x=>[x.epicAccountId,x.player]));
  assert(row.teamAccountIds.length===required&&
   row.teamAccountIds.every((id,i)=>accountMap.get(id)===names[i]),
   'Epic ID not linked '+row.id);
 }
 // A unique official calendar window proves the day, region and registered event;
 // compare against the window ID rather than relying on display names.
 const month=row.date.slice(0,7);
 if(!calendars[month])calendars[month]=read('calendar-history/'+month+'.json').sessions;
 const sessions=calendars[month];
 assert(Array.isArray(sessions)&&sessions.some(s=>
  s.sourceWindowId===windowId&&s.eventId===eventId&&s.dateJst===row.date&&
  s.region===row.region&&s.tournamentId===row.tournamentId&&s.seasonId===row.seasonId),
  'official calendar mismatch '+row.id);
 const type=groups[row.tournamentId];
 assert(!!type,'unknown manual rule '+row.id);
 const {reviewOnly,reviewReason,teamAccountIds,note,...base}=row;
 let result={...base},evidence='',rule=row.source;
 if(type==='console-vc'){
  assert(row.seasonId==='S42'&&required===1&&
   windowId.includes('S42_ConsoleVCC_SolosZB_Event8Round'),
   'unexpected console format '+row.id);
  rule=RULE_CONSOLE;
  const round1=/Event 8 · Round 1 \/ 予選/.test(row.round)&&row.kind==='予選'&&row.prize===0;
  const round2=/Event 8 · Round 2 \/ 賞金決勝/.test(row.round)&&row.kind==='賞金決勝'&&row.prize===null;
  assert(round1||round2,'unknown console event round '+row.id);
  if(round1){
   const cutoff=['EU','NAC'].includes(row.region)?2000:1000;
   assert(row.matches<=8&&row.rank<=cutoff,'console qualifier region/cap '+row.id);
   result={...result,round:row.round.replace(/\/ 予選$/,'/ 予選突破'),kind:'予選',prize:0};
   evidence='公式地域上位'+cutoff+'位以内。Round1の賞金は$0、Round2通過圏';
  }else{
   assert(row.matches<=3,'console finals match cap '+row.id);
   result={...result,prize:row.vrs*100,kind:row.vrs>0?'賞金決勝':'決勝'};
   evidence='Epic公式Attachment C: Round2の1VRにつき個人$100。受給資格や支払完了は未確認';
  }
 }else if(type==='2024-vc-qualifier'){
  assert(row.seasonId==='S30'&&required===1&&row.kind==='予選'&&
   /Round 1 \/ 予選$/.test(row.round)&&row.prize===0&&row.matches<=7,
   '2024 VC round mismatch '+row.id);
  rule=RULE_2024;
  result={...result,kind:'予選',prize:0};
  evidence='公式Round1参加記録・賞金$0。通過認定には別途公式圏内と集計完了の確認が必要';
 }else{
  assert(row.kind==='参加確認'&&row.prize===null,
   'attendance must not encode unverified prize '+row.id);
  result={...result,kind:'参加確認',prize:null};
  evidence='公式順位表上の参加・順位を確認。未確定賞金・決勝通過・衣装獲得は未認定';
 }
 result.note='ChatGPT監査済み候補：保存済みOsirion順位表・既知Epic ID・大会開催枠を照合。'
   +row.region+' '+row.rank+'位 / '+row.points+'pt / '+row.kills+'K / '+row.vrs+'VR / '
   +row.matches+'試合。'+evidence+'。根拠: '+rule;
 return {record:result,rule,sourceKey:key};
}
function main(){
 const db={results:read('results.json'),updates:read('updates.json'),players:read('players.json'),
  tournaments:read('tournaments.json'),reviewed:read('history-sync-reviewed.json'),
  review:{history:read('history-sync-review.json'),auto:read('auto-sync-review.json')},
  status:{history:read('history-sync-status.json'),auto:read('auto-sync-status.json')},
  scans:{history:read('history-sync-scan.json'),auto:read('auto-sync-scan.json')}};
 db.verifiedAccounts=linkedAccounts({players:db.players,results:db.results}).accounts;
 assert(db.verifiedAccounts.length>=300,'insufficient linked accounts');
 const queue=new Map();
 for(const name of ['history','auto'])for(const row of db.review[name].proposals){
  const other=queue.get(row.id);
  if(other&&(!sameScannedCandidate(other,row)))continue; // duplicate with conflicting review metadata remains held
  if(!other)queue.set(row.id,row);
 }
 const publishedIds=new Set(db.results.map(x=>x.id));
 const processedIds=new Set(db.reviewed.entries.map(x=>x.id));
 const selectedIds=new Set(SELECTED.map(x=>x.id));
 assert(selectedIds.size===SELECTED.length&&SELECTED.length>=60,'unexpected snapshot size');
 const now=new Date().toISOString(),calendar={},approved=[],duplicate=[],held=[],missing=[],resolved=new Set();
 const before=db.results.length;
 for(const expected of SELECTED){
  const row=queue.get(expected.id);
  if(!row){if(publishedIds.has(expected.id)||processedIds.has(expected.id))
    duplicate.push({id:expected.id,reason:'published concurrently'});
   else missing.push({id:expected.id,reason:'no longer pending'});
   continue;
  }
  if(publishedIds.has(row.id)||processedIds.has(row.id)){
   resolved.add(row.id);duplicate.push({id:row.id,reason:'already published'});continue;
  }
  if(!Object.keys(expected).every(key=>expected[key]===row[key])){
   held.push({id:row.id,reason:'score/identity/source changed since review'});continue;
  }
  let result;
  try{result=approve(row,db,db.scans,calendar);}
  catch(e){held.push({id:row.id,reason:String(e.message)});continue;}
  const record=result.record;
  const collisions=db.results.filter(x=>collision(x,record,db.players.confirmedAliases));
  if(collisions.length){
   const match=collisions.find(x=>safeSame(x,record)&&x.prize===record.prize);
   if(match&&collisions.length===1){
    resolved.add(row.id);duplicate.push({id:row.id,existingId:match.id,reason:'identical original event'});
    db.reviewed.entries.push({id:row.id,decision:'already-published',existingId:match.id,
     reviewedAt:now,source:row.source,evidence:'same event, team, rank and actual statistics'});
    processedIds.add(row.id);
   }else held.push({id:row.id,reason:'conflicting existing performance',
    existingIds:collisions.map(x=>x.id)});
   continue;
  }
  assert(record.verified===true&&record.reviewOnly!==true&&
   numberFields.every(k=>record[k]===row[k])&&
   [null,0,100,200,300].includes(record.prize),
   'unverified record/prize '+row.id);
  db.results.push(record);publishedIds.add(record.id);resolved.add(row.id);
  approved.push({id:row.id,player:row.player,region:row.region,date:row.date,
   kind:record.kind,prize:record.prize,tournamentId:record.tournamentId});
  db.reviewed.entries.push({id:row.id,recordId:row.id,decision:'published',
   reviewedAt:now,approvedBy:'ChatGPT verified review Nov 9, 2026',
   policy:'manual-verified-score-and-rule',source:row.source,officialRules:result.rule,
   evidence:'Exact source window, saved verified ranked checkpoint, player roster, no collisions'});
  processedIds.add(row.id);
 }
 for(const name of ['history','auto']){
  if(resolved.size){
   db.review[name].proposals=db.review[name].proposals.filter(x=>!resolved.has(x.id));
   db.review[name].manualReviewedAt=now;
   db.status[name].found=db.review[name].proposals.length;
   db.status[name].manualReviewCandidates=db.review[name].proposals.length;
   db.status[name].lastReviewedBatchAt=now;
   db.status[name].reviewOnlyCandidates=db.review[name].proposals.filter(x=>x.reviewOnly===true).length;
  }
 }
 if(resolved.size)db.reviewed.reviewedAt=now;
 if(approved.length){
  const id='assistant-verified-batch-20261109-late';
  assert(!db.updates.entries.some(x=>x.id===id),'update history key already used');
  db.updates.entries.unshift({id,date:new Date(Date.now()+9*3600000).toISOString().slice(0,10),
   type:'records',title:'ChatGPTが公式順位表と確認待ち'+approved.length+'件を照合・掲載',
   description:'正しいEpic ID・大会/地域/開催日・公式順位表の保存スナップショットを照合し、重複なしで参加・予選・決勝を記録。Console ZBのVR賞金は公式条件を適用、未確認賞金/衣装/突破は推測せず確認待ちに保持。',
   recordIds:approved.map(x=>x.id)});
 }
 const report={timestamp:now,requested:SELECTED.length,approved:approved.length,
  duplicates:duplicate.length,held:held.length,missing:missing.length,
  before,after:db.results.length,byTournament:approved.reduce((acc,x)=>(acc[x.tournamentId]=(acc[x.tournamentId]||0)+1,acc),{}),
  cashAwarded:approved.reduce((s,x)=>s+(x.prize||0),0),
  remaining:{history:db.review.history.proposals.length,auto:db.review.auto.proposals.length},
  approvedRows:approved,heldRows:held,duplicatesResolved:duplicate};
 console.log('AOT_DIRECT_REVIEW_NOV09 '+JSON.stringify(report));
 if(process.argv.includes('--dry-run')||!resolved.size)return report;
 for(const [name,obj] of Object.entries({
  'results.json':db.results,'updates.json':db.updates,
  'history-sync-review.json':db.review.history,'auto-sync-review.json':db.review.auto,
  'history-sync-status.json':db.status.history,'auto-sync-status.json':db.status.auto,
  'history-sync-reviewed.json':db.reviewed
 }))write(name,obj);
 return report;
}
if(require.main===module)main();
module.exports={main,SELECTED,groups};